package com.talentsync.applicationservice.service;
import com.talentsync.applicationservice.client.*; import com.talentsync.applicationservice.dto.ApplicationResponse; import com.talentsync.applicationservice.entity.*; import com.talentsync.applicationservice.repository.ApplicationRepository; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.time.LocalDate; import java.util.*;
@Service public class ApplicationService { private final ApplicationRepository repo; private final JobClient jobs; private final RecruitmentClient recruitment; private final Path uploadDir;
 public ApplicationService(ApplicationRepository r,JobClient j,RecruitmentClient c,@org.springframework.beans.factory.annotation.Value("${app.upload-dir}") String dir){repo=r;jobs=j;recruitment=c;uploadDir=Paths.get(dir).toAbsolutePath().normalize();}
 public ApplicationResponse submit(Long candidateId,Long jobId,String cover,MultipartFile file){ if(file==null||file.isEmpty()) throw new IllegalArgumentException("A resume is required"); String name=Optional.ofNullable(file.getOriginalFilename()).orElse("resume"); if(!name.toLowerCase().matches(".*\\.(pdf|doc|docx)$")) throw new IllegalArgumentException("Resume must be PDF, DOC, or DOCX"); if(repo.existsByCandidateIdAndJobId(candidateId,jobId)) throw new IllegalStateException("You have already applied for this job"); try{Object job=jobs.getJob(jobId); validateOpenJob(job); Files.createDirectories(uploadDir); String stored=UUID.randomUUID()+"-"+name.replaceAll("[^a-zA-Z0-9._-]","_"); Files.copy(file.getInputStream(),uploadDir.resolve(stored)); JobApplication a=new JobApplication();a.setCandidateId(candidateId);a.setJobId(jobId);a.setCoverLetter(cover);a.setResumeFileName(name);a.setResumeStoragePath(stored);a=repo.save(a); try{recruitment.createRecord(new RecruitmentClient.RecordRequest(a.getId(),candidateId,jobId));}catch(Exception e){repo.delete(a);Files.deleteIfExists(uploadDir.resolve(stored));throw new IllegalStateException("Recruitment tracking is unavailable; application was not saved");} return ApplicationResponse.from(a);}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("Could not store resume",e);} }
 private void validateOpenJob(Object job){if(!(job instanceof Map<?,?> values))throw new IllegalStateException("Could not verify job availability");if(!"ACTIVE".equals(String.valueOf(values.get("status"))))throw new IllegalArgumentException("This job is no longer accepting applications");Object deadline=values.get("applicationDeadline");if(deadline!=null&&LocalDate.parse(String.valueOf(deadline)).isBefore(LocalDate.now()))throw new IllegalArgumentException("The application deadline has passed");}
 public List<ApplicationResponse> mine(Long id){return repo.findByCandidateIdOrderByAppliedAtDesc(id).stream().map(ApplicationResponse::from).toList();} public List<ApplicationResponse> forJob(Long id){return repo.findByJobIdOrderByAppliedAtDesc(id).stream().map(ApplicationResponse::from).toList();} public ApplicationResponse get(Long id){return ApplicationResponse.from(repo.findById(id).orElseThrow(()->new NoSuchElementException("Application not found")));} public ApplicationResponse updateStatus(Long id, ApplicationStatus status){JobApplication application=repo.findById(id).orElseThrow(()->new NoSuchElementException("Application not found"));application.setStatus(status);return ApplicationResponse.from(repo.save(application));} public Path resume(Long id){return uploadDir.resolve(repo.findById(id).orElseThrow(()->new NoSuchElementException("Application not found")).getResumeStoragePath()).normalize();}}
